-- 190_replace_decision_162_2020_insurance_reserve_for_egas47_financial_instruments_ocr_corrupted_two_rows_without_preamble_with_page_break_in_article_1.sql
--
-- إعادة رفع قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم (162) لسنة 2020 بتاريخ 2020/9/30 بشأن تكوين احتياطى لمواجهة مخاطر آثار تطبيق معيار المحاسبة المصرى رقم (47) الأدوات المالية على شركات التأمين:
-- ديباجة ومادتان (صفحتان)، بلا فصول ولا قواعد مرفقة (فمفاتيح المواد كلها article_suffix_order = 0).
--
-- ===== الحالة السابقة (مراجعة الـ153 وثيقة، أولوية OCR) =====
-- مخزَّن بالبذور صفّان (article_no = 1 بـ1096 حرفاً و2 بـ273 حرفاً، بلا عنوان وبلا hierarchical_location) من OCR رديء للصفحتين الممسوحتين، وبهما:
-- (1) لا ديباجة: غاب كل ما قبل "قرر" (القانونان 10 لسنة 1981 و10 لسنة 2009، وقرار رئيس مجلس الوزراء 1871 لسنة 2020، وقرار وزير الاستثمار 110 لسنة 2015 المعدل بالقرار 69 لسنة 2019، وقرار الهيئة 70 لسنة 2016، وتاريخ جلسة المجلس 2020/9/30)، ولا عنوان القرار ولا رقمه ولا تاريخه؛
-- (2) المادة 1 مشوهة فى أرقامها الجوهرية: النسبة "(1%)" مخزَّنة "(901)"، وتاريخ نهاية العام المالى "2020/6/30" مخزَّن "5"، والبند 1 مقطوع عند "من م" (ناقص "عوقات")؛ وبين البند 4 والبند 5 (حدّ الصفحتين) ترويسة الصفحة الثانية وتذييل الأولى مشوهان (القرية الذكية، والرقم البريدى، والهاتف والفاكس، و"نبنى الجسور لا الحواجز"، و"رئيس الهيئة")، فالبند 5 مفصول عن المادة 1 وملحق بالصف التالى لها؛
-- (3) المادة 2 تحمل بعد نصها سطر التوقيع "رئيس مجلس إدارة العيشة" بلا اسم الموقِّع وتذييل الصفحة الثانية مشوهاً؛
-- (4) أرقام هندية متبقية، ونهايات أسطر CRLF، وتاريخ سريان هو تاريخ تشغيل البذر (2026-10-09) لا تاريخ القرار.
-- فلا يصلح النص المخزَّن للاستشهاد الرسمى ولا لإدخاله إلى سياق نموذج اللغة: نسبة الاحتياطى (1%)، وتاريخ العام المالى (2020/6/30)، وبند التنسيق، كلها مفقودة أو محرفة.
--
-- ===== المصدر والمنهجية =====
-- PDF من صفحتين (61 كيلوبايت) قدّمه صاحب المشروع باسم UG51839UG51840 (هو الاسم نفسه فى official_url المسجَّل فى laws)؛ هو صورتان ممسوحتان بالأبيض والأسود (JBIG2، 200 نقطة للبوصة) على ورق الهيئة، وبلا طبقة نص. قُرئ النص من الصورتين الأصليتين مباشرةً مقاطعَ مكبّرة، وكُبّرت أسطر الأرقام (رقم القرار 162 وتاريخه 2020/9/30 والقانونان وقرار رئيس مجلس الوزراء 1871 وقرار وزير الاستثمار 110 والقرار المعدل 69 وقرار الهيئة 70 والنسبة 1% وتاريخ العام المالى 2020/6/30 ورقم المعيار 47) وقُرئت رقماً رقماً (الأرقام المطبوعة هندية).
-- ثم قوبل النص المقروء بمخرجات OCR مستقل (tesseract ara) على الصفحتين: لم يظهر فرق فى لفظ غير ضجيج التعرف (التشوهات والترويسة والتذييل وبقايا الختم)؛ والفرق الوحيد فى لفظ حقيقى كلمة "معوقات" فى آخر البند 1 (يمر ختم الهيئة فوق آخرها فى الصورة، والكلمة مقروءة بوضوح كافٍ). والأرقام مصدرها القراءة البصرية لا الـOCR.
-- حُذفت ترويسة كل صفحة (شعار "الهيئة العامة للرقابة المالية FINANCIAL REGULATORY AUTHORITY" وسطر "رئيس الهيئة")، وتذييلها (القرية الذكية والرقم البريدى والهاتف والفاكس وموقع الهيئة وشعار "نبنى الجسور لا الحواجز / Building Bridges not Walls" ورقم الصفحة "1")، وسطر جهة الإصدار "مجلس إدارة الهيئة العامة للرقابة المالية" الذى يلى العنوان، وكلمة "قرر"، وختم "مكتب رئيس الهيئة" ورقمه المكتوب بخط اليد (46076) وتوقيع اليد (ليست من النص).
-- عنوان القرار ورقمه وتاريخه وموضوعه فى hierarchical_location للديباجة كما طُبعت (وكُتب فيها "العامة للرقابة المالية" بعد "الهيئة" بالصيغة الموحدة لعناوين الهجرات الأخرى؛ المطبوع "قرار مجلس إدارة الهيئة رقم (162) لسنة 2020 بتاريخ 2020/9/30"). الديباجة (article_no = 0 بعنوان "ديباجة القرار") من "بعد الاطلاع" إلى آخر "وبعد موافقة مجلس إدارة الهيئة"؛ وبعد "قرر" المادتان بعنوانين وسطيين "(المادة الأولي)" و"(المادة الثانية)" (كتبت الأولى بالياء فى المطبوع) فعنوانا الصفين "المادة الأولى" و"المادة الثانية". وفى المادة 1 البنود "1- ..." إلى "5- ..." سطراً لكل بند، والبند 5 يبدأ الصفحة الثانية (فهو من المادة 1 لا من الثانية). والتوقيع باقٍ فى المادة 2 سطرين ("رئيس مجلس إدارة الهيئة / د. محمد عمران") كما طُبع.
-- لا تعديل على لفظ المطبوع. أُبقيت كتابته بلا تعديل: "الالكتروني" فى المادة 2 بلا همزة، وجملة "ويتعين على مجلس إدارة الشركة متابعة ... من الآتي :" كما طُبعت (وهى مسطَّرة فى الصورة)، والعنوان الفرعى للمعيار "الأدوات المالية" بلا حرف عطف. وأُسقطت علامة الضمة فى "يُنشر" ضمن إسقاط علامات التشكيل الصغيرة.
-- الأرقام لاتينية (المطبوعة هندية)، والنسبة "%" كما طُبعت، وضُبطت المسافات حول الفاصلة والفاصلة المنقوطة والنقطتين (" ، " و" ؛" و" :").
--
-- ===== الهيكل =====
-- 3 صفوف، 3 نسخ (version_no = 1): ديباجة (article_no = 0) ثم المادتان 1 و2 بأرقامهما الأصلية. أُبقى مفتاحا المادتين المخزَّنتين (1، 0) و(2، 0) فلا تعيد بذور 004/005/006 إدراج الصفوف القديمة (إدراج laws فيها ON CONFLICT DO NOTHING، وإدراج المواد مبنى على RETURNING فلا يعمل مع قانون موجود).
--
-- ===== التاريخ =====
-- effective_from = 2020-09-30: تاريخ القرار المطبوع على الصفحة (معلن)؛ القرار بلا بند للعمل به (المادة 2 تنص على النشر فقط) ولا يظهر عليه بيان نشر، ولم يُتحقق من تاريخ نشره بالوقائع المصرية، فلم يُفترض يوم بعد النشر. ويُراجع المراجع القانونى هذا التاريخ. كان القديم تاريخ تشغيل البذر لا تاريخ سريان.
-- ولا تُعدَّل بيانات laws (التاريخ ورقم القرار والعنوان) فى هذه الهجرة.
--
-- ===== قابلية إعادة التشغيل =====
-- الحذف مشروط بألا تكون الحالة نظيفة (3 صفوف بديباجة سليمة والمادة 2 موجودة)؛ والإدراج ON CONFLICT DO NOTHING. تحقق الختام محصور فى هذا القرار ويفشل عند أى انحراف (عدد، أو بقايا تلف، أو محتوى المواد، أو إجمالى الطول 1508 حرفاً).
--
-- ملاحظة تشغيلية: المواد الجديدة بلا embedding؛ يلزم scripts/backfill-embeddings.js بعد النشر.
BEGIN;
DO $fix190$
DECLARE
  v_law_id uuid;
  v_n int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 162 AND law_year = 2020 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[190] القرار 162/2020 غير موجود فى laws — تخطّى';
    RETURN;
  END IF;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law_id) = 3
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND title = 'ديباجة القرار' AND body LIKE 'بعد الاطلاع%')
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0) THEN
    RAISE NOTICE '[190] القرار 162/2020 نظيف بالفعل — تخطّى الحذف';
  ELSE
    SELECT count(*) INTO v_n FROM articles WHERE law_id = v_law_id;
    DELETE FROM articles WHERE law_id = v_law_id;
    RAISE NOTICE '[190] أُزيلت % مادة من القرار 162/2020 (نص مخزَّن صفّان بلا ديباجة والمادة الأولى مقطوعة بين الصفحتين وفيها ترويسة وتذييل مشوهان وبلا اسم الموقِّع)', v_n;
  END IF;
END
$fix190$;

WITH ins0_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 0, 0, $h0$قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم 162 لسنة 2020 بتاريخ 2020/9/30 بشأن تكوين احتياطي لمواجهة مخاطر آثار تطبيق معيار المحاسبة المصري رقم (47) الأدوات المالية على شركات التأمين$h0$, $t0_0$ديباجة القرار$t0_0$, $b0_0$بعد الاطلاع على قانون الإشراف والرقابة على التأمين في مصر الصادر بالقانون رقم (10) لسنة 1981 ولائحته التنفيذية ؛
وعلى القانون رقم (10) لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية ؛
وعلى قرار رئيس مجلس الوزراء رقم (1871) لسنة 2020 ؛
وعلى قرار وزير الاستثمار رقم (110) لسنة 2015 بشأن معايير المحاسبة المصرية والمعدل بقرار وزير الاستثمار والتعاون الدولي رقم (69) لسنة 2019 ؛
وعلى قرار مجلس إدارة الهيئة رقم (70) لسنة 2016 بإصدار دليل تطبيق معايير المحاسبة المصرية على قطاع التأمين ؛
وبعد موافقة مجلس إدارة الهيئة بجلسته المنعقدة بتاريخ 2020/9/30 ؛$b0_0$
  FROM laws WHERE law_no = 162 AND law_year = 2020 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2020-09-30', 'active' FROM ins0_0;

WITH ins1_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 0, NULL, $t1_0$المادة الأولى$t1_0$, $b1_0$تلتزم شركات التأمين بتكوين احتياطي لمواجهة مخاطر آثار تطبيق معيار المحاسبة المصري رقم (47) الأدوات المالية ، بما يعادل نسبة (1%) من إجمالي الأصول وذلك من صافي أرباح العام بعد احتجاز الضريبة عن العام المالي المنتهي في 2020/6/30 ، على أن يتم إدراجه ضمن حقوق المساهمين ولا يتم استخدامه إلا بعد موافقة الهيئة.
ويتعين على مجلس إدارة الشركة متابعة الالتزام الوارد بالفقرة السابقة ، ومراعاة التحقق من الآتي :
1- توفير المتطلبات اللازمة لتطبيق المعيار وإزالة ما قد يواجه التنفيذ من معوقات.
2- تحديد نماذج الأعمال التي ستستخدم عند تطبيق المعيار.
3- قياس مدى كفاية نظم المعلومات وتوافر الموارد البشرية والخبرات.
4- تطوير بيئة إدارة المخاطر وسياسات الاكتتاب والاستثمار للشركة.
5- التنسيق بين الإدارات المختلفة بالشركة ومن بينها الإدارات الفنية والمالية وإدارة المخاطر وإدارة تكنولوجيا المعلومات والمراجعة الداخلية وكافة الإدارات المعنية في هذا الشأن.$b1_0$
  FROM laws WHERE law_no = 162 AND law_year = 2020 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2020-09-30', 'active' FROM ins1_0;

WITH ins2_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 0, NULL, $t2_0$المادة الثانية$t2_0$, $b2_0$ينشر هذا القرار في الوقائع المصرية وعلى الموقع الالكتروني للهيئة.
رئيس مجلس إدارة الهيئة
د. محمد عمران$b2_0$
  FROM laws WHERE law_no = 162 AND law_year = 2020 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2020-09-30', 'active' FROM ins2_0;

DO $verify190$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 162 AND law_year = 2020 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[190] القرار 162/2020 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 3 THEN RAISE EXCEPTION '[190] عدد المواد % بدل 3', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2020-09-30';
  IF v_v <> 3 THEN RAISE EXCEPTION '[190] عدد النسخ % بدل 3', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%الشيئة%' OR body LIKE '%الهيئكة%' OR body LIKE '%العيشة%' OR body LIKE '%الممتصري%' OR body LIKE '%القرية الذكية%' OR body LIKE '%الرقم البريدى%' OR body LIKE '%الرقم اليريدى%' OR body LIKE '%تليفون%' OR body LIKE '%نبنى الجسور%' OR body LIKE '%Building Bridges%' OR body LIKE '%WWW%' OR body LIKE '%FRA.GOV%' OR body LIKE '%الحواجز%' OR body LIKE '%الصواجز%' OR body LIKE '%معوقاق%' OR body LIKE '%٠%' OR body LIKE '%١%' OR body LIKE '%�%' OR body LIKE '%األ%' OR body LIKE '%اإل%' OR body LIKE '%اآل%' OR body LIKE '%ال يقل%' OR body LIKE '%(961)%' OR body LIKE '%(417)%' OR body LIKE '%(901)%' OR body LIKE '%سمبنى%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[190] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND body LIKE 'بعد الاطلاع على قانون الإشراف والرقابة على ال%' AND body LIKE '%ته المنعقدة بتاريخ 2020/9/30 ؛' AND body LIKE '%رقم (10) لسنة 1981 ولائحته التنفيذية ؛%' AND body LIKE '%رقم (10) لسنة 2009 بتنظيم الرقابة على الأسواق%' AND body LIKE '%قرار رئيس مجلس الوزراء رقم (1871) لسنة 2020 ؛%' AND body LIKE '%قرار وزير الاستثمار رقم (110) لسنة 2015%' AND body LIKE '%والتعاون الدولي رقم (69) لسنة 2019 ؛%' AND body LIKE '%قرار مجلس إدارة الهيئة رقم (70) لسنة 2016 بإصدار دليل تطبيق%' AND body LIKE '%على قطاع التأمين ؛%' AND body LIKE '%المنعقدة بتاريخ 2020/9/30 ؛') THEN RAISE EXCEPTION '[190] ديباجة غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE 'تلتزم شركات التأمين بتكوين احتياطي لمواجهة مخ%' AND body LIKE '%الإدارات المعنية في هذا الشأن.' AND body LIKE '%رقم (47) الأدوات المالية ، بما يعادل نسبة (1_) من إجمالي الأصول%' AND body LIKE '%المنتهي في 2020/6/30 ، على أن يتم إدراجه ضمن حقوق المساهمين%' AND body LIKE '%إلا بعد موافقة الهيئة.%' AND body LIKE '%ومراعاة التحقق من الآتي :%' AND body LIKE '%1- توفير المتطلبات اللازمة لتطبيق المعيار%' AND body LIKE '%2- تحديد نماذج الأعمال%' AND body LIKE '%3- قياس مدى كفاية نظم المعلومات%' AND body LIKE '%4- تطوير بيئة إدارة المخاطر%' AND body LIKE '%5- التنسيق بين الإدارات المختلفة بالشركة%' AND body LIKE '%كافة الإدارات المعنية في هذا الشأن.') THEN RAISE EXCEPTION '[190] المادة 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0 AND body LIKE 'ينشر هذا القرار في الوقائع المصرية وعلى الموق%' AND body LIKE '%د. محمد عمران' AND body LIKE '%على الموقع الالكتروني للهيئة.%' AND body LIKE '%رئيس مجلس إدارة الهيئة%' AND body LIKE '%د. محمد عمران') THEN RAISE EXCEPTION '[190] المادة 2 غير سليم'; END IF;
  IF v_len <> 1508 THEN RAISE EXCEPTION '[190] إجمالى طول المواد % بدل 1508', v_len; END IF;
  RAISE NOTICE '[190] القرار 162/2020: 3 مواد و3 نسخ، إجمالى % حرف', v_len;
END
$verify190$;

COMMIT;
